-- Berkeley places, round two: 760 more stores, food spots, libraries, residence halls, co-ops,
-- apartments, Greek houses, campus buildings, landmarks, and transit stops (163 store, 285 restaurant, 22 library, 137 residence, 119 campus, 7 transit, 27 other),
-- so most people can find their store and drop-off spot without adding one.
--
-- Source: OpenStreetMap (© OpenStreetMap contributors, ODbL), pulled 2026-10-15 for the City of
-- Berkeley plus the big-box stores and BART/Amtrak stations people use in Emeryville, Albany,
-- El Cerrito, Richmond, and North Oakland. A handful of spots the map doesn't label (Sproul Plaza,
-- Unit 1 / Unit 3, Foothill, the dining halls) are placed by hand.
--
-- Chains get their street or town in the name ("Safeway (Shattuck Ave)") because pickers show the
-- name only. Like create_place(), a row is skipped when a place within 150 m already has a matching
-- name, so places people added from Apple Maps are not duplicated.

insert into public.places (id, campus_id, name, detail, kind, address, lat, lng)
select v.id::uuid, 'c0000000-0000-0000-0000-000000000001', v.name, v.detail, v.kind::public.place_kind, v.address, v.lat, v.lng
